head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setColumnDisplayFormat]<br/>Body Column 정보를 사용하여 특정 Column 의 displayFormat 속성을 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터는 Row 가 MultiLine 이어도 모든 Column 은 고유의 인덱스값을 갖습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Body Row MultiLine 구성)
//  - gBody 에 <w2:row> 2개 -> 한 데이터 Row 가 2 Line 으로 표시
//  - 1줄 = col1(인덱스0:text) / col2(인덱스1:number, dataType="number")
//  - 2줄 = col3(인덱스2:date, dataType="date") / col4(인덱스3:time, dataType="time")
//  - Row 가 MultiLine 이어도 col1~col4 는 각각 고유 인덱스(0~3) 를 가짐
//  - 이 고유 인덱스로 setColumnDisplayFormat(인덱스, format) 호출 시 해당 컬럼만 정확히 포맷 적용됨
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // MultiLine 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Body 가 MultiLine(2줄). 한 데이터 Row 가 2줄에 걸쳐 표시됨. 1줄 col1(0:text, 숫자형)/col2(1:number), 2줄 col3(2:date, 초기 yyyy.MM.dd)/col4(3:time, 초기 HH.mm.ss) 고유 인덱스. 각 컬럼 dataType 이 서로 다름. 데이터 Row 3개.\n[절차] columnInfo(0~3) 선택 후 (setColumnDisplayFormat 실행) -> 선택한 고유 인덱스 컬럼에만 dataType 에 맞는 displayFormat 적용. 변경 전/후 셀 표시값을 비교 출력.\n[확인] MultiLine 이어도 col1~col4 는 고유 인덱스(0~3)로 각각 지목되어 해당 컬럼 셀 표시 포맷이 실제로 변경됨(다른 컬럼 영향 없음). idx0:text 1234567 -> 123-4567 / idx1:number 1250000 -> 1,250,000.00 / idx2:date 2025.01.15 -> 2025/01/15 / idx3:time 09.15.30 -> 09:15:30. getColumnID(인덱스) 매핑도 함께 출력."', '', 'label1');

    // dataList 생성 + 초기값 바인딩
    //  - col1:text / col2:number / col3:date(yyyyMMdd) / col4:time(HHmmss)
    let strData = '';
    strData += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strData += '<w2:columnInfo>';
    strData += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strData += '<w2:column id="col2" name="col2" dataType="number"></w2:column>';
    strData += '<w2:column id="col3" name="col3" dataType="date"></w2:column>';
    strData += '<w2:column id="col4" name="col4" dataType="time"></w2:column>';
    strData += '</w2:columnInfo>';
    strData += '<w2:data use="true"></w2:data>';
    strData += '</w2:dataList>';
    $p.data.create(strData);
    dlt_bind.setJSON([
        { "col1": "1234567", "col2": "1250000", "col3": "20250115", "col4": "091530" },
        { "col1": "9876543", "col2": "980500", "col3": "20250220", "col4": "143005" },
        { "col1": "5550000", "col2": "1430250", "col3": "20250312", "col4": "180045" }
    ]);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // target 생성 (Body Row MultiLine : gBody 에 <w2:row> 2개)
    //  - 1줄 : col1(0:text) / col2(1:number)
    //  - 2줄 : col3(2:date) / col4(3:time)
    //  - Row 가 MultiLine 이어도 모든 Column 은 고유 인덱스(0~3)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" id="" style="width:560px;height:340px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol1" value="코드(text)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol2" value="매출(number)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol3" value="개설일(date)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="개점시각(time)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    // index 0 : col1 (text, 숫자형 문자열 -> ###-#### 마스크로 변화 명확)
    strTarget += '<w2:column width="280" inputType="text" dataType="text" id="col1" dataList="col1"></w2:column>';
    // index 1 : col2 (number, 1줄 마지막, 고유 인덱스 1)
    strTarget += '<w2:column width="*" inputType="text" dataType="number" id="col2" dataList="col2"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    // index 2 : col3 (date, 2줄 첫 컬럼, 고유 인덱스 2. 초기 displayFormat=yyyy.MM.dd -> 적용 시 yyyy/MM/dd 로 변화)
    strTarget += '<w2:column width="280" inputType="text" dataType="date" displayFormat="yyyy.MM.dd" id="col3" dataList="col3"></w2:column>';
    // index 3 : col4 (time, 2줄 마지막, 고유 인덱스 3. 초기 displayFormat=HH.mm.ss -> 적용 시 HH:mm:ss 로 변화)
    strTarget += '<w2:column width="*" inputType="text" dataType="time" displayFormat="HH.mm.ss" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// [실행] setColumnDisplayFormat : 선택한 컬럼(고유 누적 인덱스) 에만 displayFormat 속성을 설정
//  - MultiLine(2줄) 이어도 col1~col4 는 고유 인덱스(0~3) 로 정확히 지목됨
//  - 선택 인덱스의 dataType 에 맞는 포맷을 적용 : idx1=number(#,##0.00) / idx2=date(yyyy-MM-dd) / idx3=time(HH:mm:ss) / idx0=text(####)
//  - 적용 후 해당 컬럼 셀 표시값 + getColumnID(인덱스) 매핑을 출력하여 고유 인덱스로 해당 컬럼만 포맷됨을 확인
scwin.btn_setColumnDisplayFormat_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());
    let colID = target1.getColumnID(columnInfo);   // MultiLine Row 에서도 col1~col4 는 고유 인덱스(0~3)

    // dataType 에 맞는 displayFormat 선택 (적용 시 셀 표시값이 눈에 띄게 바뀌도록)
    //  text: 1234567 -> 123-4567 / number: 1250000 -> 1,250,000.00 / date: 2025.01.15 -> 2025/01/15 / time: 09.15.30 -> 09:15:30
    let fmtMap = {
        0: "###-####",      // text
        1: "#,##0.00",      // number
        2: "yyyy/MM/dd",    // date
        3: "HH:mm:ss"       // time
    };
    let displayFormat = fmtMap[columnInfo];

    // 셀 표시값 수집 헬퍼
    let readCells = function () {
        let arr = [];
        for (let r = 0; r < 3; r++) {
            let td = document.querySelector("td[id*='target1_cell_" + r + "_" + columnInfo + "']");
            arr.push(td ? td.textContent.trim() : "(셀없음)");
        }
        return arr;
    };

    // 고유 인덱스로 해당 컬럼에만 displayFormat 설정
    target1.setColumnDisplayFormat(columnInfo, displayFormat);

    // 적용 후 표시값
    let after = readCells();

    wf_body_bottom.getObj("scwin").setReturnValue(
        "setColumnDisplayFormat(" + columnInfo + ", '" + displayFormat + "') [고유 인덱스 " + columnInfo + " -> getColumnID : " + colID + "]"
        + "\n[셀 표시값] " + after.join(', ')
    );
}
